<?php defined('BASEPATH') OR exit('No direct script access allowed');class Contact_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function submit($d,$auth){$now=date('Y-m-d H:i:s');$id=$this->uuid();$r=array('id'=>$id,'request_number'=>'SUP-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)),'organization_id'=>$auth['organizationId']??NULL,'user_id'=>$auth['sub']??($d['userId']??NULL),'name'=>trim($d['name']),'email'=>strtolower(trim($d['email'])),'phone'=>$d['phone']??NULL,'country'=>$d['country']??NULL,'company'=>$d['company']??NULL,'category'=>$d['category'],'subject'=>$d['subject'],'message'=>$d['message'],'preferred_contact_method'=>$d['preferredContactMethod']??'email','priority'=>'normal','status'=>'new','department'=>'general','source'=>'web','created_at'=>$now,'updated_at'=>$now);$this->db->insert('contact_requests',$r);$this->db->insert('contact_messages',array('id'=>$this->uuid(),'request_id'=>$id,'author_type'=>'user','author_id'=>$r['user_id'],'author_name'=>$r['name'],'body'=>$r['message'],'is_internal'=>0,'created_at'=>$now));return $this->view($r);}function mine($uid,$id=NULL){$this->db->where('user_id',$uid);if($id)$this->db->where('id',$id);$rows=$this->db->order_by('created_at','DESC')->get('contact_requests')->result_array();if($id)return $rows?$this->view($rows[0]):NULL;return array_map(array($this,'view'),$rows);}function messages($rid,$uid){if(!$this->db->where(array('id'=>$rid,'user_id'=>$uid))->count_all_results('contact_requests'))return NULL;$r=$this->db->where(array('request_id'=>$rid,'is_internal'=>0))->order_by('created_at')->get('contact_messages')->result_array();return array_map(function($x){return array('id'=>$x['id'],'requestId'=>$x['request_id'],'authorType'=>$x['author_type'],'authorId'=>$x['author_id'],'authorName'=>$x['author_name'],'body'=>$x['body'],'isInternal'=>(bool)$x['is_internal'],'createdAt'=>$x['created_at']);},$r);}function ai_start($message,$name,$email,$org){$id=$this->uuid();$now=date('Y-m-d H:i:s');$msgs=array(array('role'=>'user','content'=>$message));$this->db->insert('contact_ai_sessions',array('id'=>$id,'organization_id'=>$org,'name'=>$name,'email'=>$email,'messages'=>json_encode($msgs),'created_at'=>$now,'updated_at'=>$now));return array($id,$msgs);}function ai_get($id){return $this->db->where('id',$id)->get('contact_ai_sessions')->row_array();}function ai_save($id,$msgs){$this->db->where('id',$id)->update('contact_ai_sessions',array('messages'=>json_encode($msgs),'updated_at'=>date('Y-m-d H:i:s')));}function admin_list($filters,$p,$pp){$this->db->from('contact_requests');foreach($filters as $k=>$v)if($v)$this->db->where($k,$v);$n=$this->db->count_all_results();foreach($filters as $k=>$v)if($v)$this->db->where($k,$v);$rows=$this->db->order_by('created_at','DESC')->limit($pp,($p-1)*$pp)->get('contact_requests')->result_array();return array('items'=>array_map(array($this,'view'),$rows),'total'=>$n);}function admin_get($id){$r=$this->db->where('id',$id)->get('contact_requests')->row_array();return $r?$this->view($r):NULL;}function admin_messages($id){$r=$this->db->where('request_id',$id)->order_by('created_at')->get('contact_messages')->result_array();return array_map(function($x){return array('id'=>$x['id'],'requestId'=>$x['request_id'],'authorType'=>$x['author_type'],'authorId'=>$x['author_id'],'authorName'=>$x['author_name'],'body'=>$x['body'],'isInternal'=>(bool)$x['is_internal'],'createdAt'=>$x['created_at']);},$r);}function history($id){$r=$this->db->where('request_id',$id)->order_by('created_at')->get('contact_status_history')->result_array();return array_map(function($x){return array('id'=>$x['id'],'fromStatus'=>$x['from_status'],'toStatus'=>$x['to_status'],'changedByUserId'=>$x['changed_by_user_id'],'createdAt'=>$x['created_at']);},$r);}function respond($id,$uid,$d){if(!$this->db->where('id',$id)->count_all_results('contact_requests'))return NULL;$r=array('id'=>$this->uuid(),'request_id'=>$id,'author_type'=>'staff','author_id'=>$uid,'author_name'=>$d['authorName']??'Support','body'=>$d['body'],'is_internal'=>!empty($d['isInternal']), 'created_at'=>date('Y-m-d H:i:s'));$this->db->insert('contact_messages',$r);if(empty($d['isInternal']))$this->transition($id,$uid,'awaiting_customer');return $this->admin_messages($id)[count($this->admin_messages($id))-1];}function assign($id,$uid,$d){$r=$this->db->where('id',$id)->get('contact_requests')->row_array();if(!$r)return NULL;$set=array('assigned_user_id'=>$d['userId']??NULL,'assigned_agent_id'=>$d['agentId']??NULL,'priority'=>$d['priority']??$r['priority'],'department'=>$d['department']??$r['department'],'status'=>'assigned','updated_at'=>date('Y-m-d H:i:s'));$this->db->where('id',$id)->update('contact_requests',$set);$this->db->insert('contact_status_history',array('id'=>$this->uuid(),'request_id'=>$id,'from_status'=>$r['status'],'to_status'=>'assigned','changed_by_user_id'=>$uid,'created_at'=>date('Y-m-d H:i:s')));return $this->admin_get($id);}function transition($id,$uid,$to){$r=$this->db->where('id',$id)->get('contact_requests')->row_array();if(!$r)return NULL;$now=date('Y-m-d H:i:s');$set=array('status'=>$to,'updated_at'=>$now);if($to==='resolved')$set['resolved_at']=$now;if($to==='closed')$set['closed_at']=$now;$this->db->where('id',$id)->update('contact_requests',$set);$this->db->insert('contact_status_history',array('id'=>$this->uuid(),'request_id'=>$id,'from_status'=>$r['status'],'to_status'=>$to,'changed_by_user_id'=>$uid,'created_at'=>$now));return $this->admin_get($id);}function dashboard(){$total=$this->db->count_all('contact_requests');$open=$this->db->where_not_in('status',array('resolved','closed'))->count_all_results('contact_requests');$urgent=$this->db->where('priority','urgent')->where_not_in('status',array('resolved','closed'))->count_all_results('contact_requests');$rows=$this->db->select('status,COUNT(*) n')->group_by('status')->get('contact_requests')->result_array();$by=array();foreach($rows as $r)$by[$r['status']]=(int)$r['n'];return array('total'=>$total,'open'=>$open,'urgent'=>$urgent,'byStatus'=>$by,'generatedAt'=>date('c'));}function view($r){return array('id'=>$r['id'],'requestNumber'=>$r['request_number'],'name'=>$r['name'],'email'=>$r['email'],'phone'=>$r['phone'],'country'=>$r['country'],'company'=>$r['company'],'category'=>$r['category'],'subject'=>$r['subject'],'message'=>$r['message'],'preferredContactMethod'=>$r['preferred_contact_method'],'priority'=>$r['priority'],'status'=>$r['status'],'department'=>$r['department'],'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
